import * as React from "react";

import { cn } from "../lib/utils";

import styles from "./detail.module.css";

function Detail({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"dl"> & { ref?: React.Ref<HTMLDListElement> }) {
  return <dl ref={ref} data-slot="detail" className={cn(styles.detail, className)} {...props} />;
}

function DetailLabel({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"dt"> & { ref?: React.Ref<HTMLElement> }) {
  return (
    <dt ref={ref} data-slot="detail-label" className={cn(styles.label, className)} {...props} />
  );
}

function DetailValue({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"dd"> & { ref?: React.Ref<HTMLElement> }) {
  return (
    <dd ref={ref} data-slot="detail-value" className={cn(styles.value, className)} {...props} />
  );
}

function DetailGroup({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & { ref?: React.Ref<HTMLDivElement> }) {
  return (
    <div ref={ref} data-slot="detail-group" className={cn(styles.group, className)} {...props} />
  );
}

function DetailGroupHeader({
  className,
  level = 3,
  action,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & {
  level?: 2 | 3 | 4 | 5 | 6;
  action?: React.ReactNode;
  ref?: React.Ref<HTMLDivElement>;
}) {
  const Heading = `h${level}` as const;
  return (
    <div
      ref={ref}
      data-slot="detail-group-header"
      className={cn(styles.header, className)}
      {...props}
    >
      <Heading className={styles.title}>{children}</Heading>
      {action && <div className={styles.action}>{action}</div>}
    </div>
  );
}

export { Detail, DetailGroup, DetailGroupHeader, DetailLabel, DetailValue };

.detail {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-4);
  min-width: 0;
  margin: 0;
}
.label {
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-caption-font-weight);
  letter-spacing: var(--v4-type-caption-letter-spacing);
  color: var(--v4-muted);
}
.value {
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  min-width: 0;
  margin: 0;
  color: var(--v4-ink);
  overflow-wrap: anywhere;
}
.group {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-16);
  min-width: 0;
}
.header {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
}
.title {
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  color: var(--v4-ink);
}
.action {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-4);
}
